-- 0031_schedule_series.sql — V23 Step 11: workouts created together know
-- they belong together.
--
-- schedule/new.tsx already turns a repeat ("Sun + Wed for 8 weeks") into one
-- concrete scheduled_workouts row per date — the right call, every row stays
-- individually editable and the package trigger, money and reminder views
-- work on it unchanged. What was missing is the link between those rows, so
-- moving a weekly slot meant editing every occurrence by hand.
--
-- series_id: one uuid generated by the app per repeat insert, stamped on every
-- row of the batch. Null = a one-off. No FK (there is no series table — the
-- rows ARE the series) and no RLS change: the trainer already owns every row,
-- and the id grants nothing new.
--
-- The rule every series-scoped write follows (lib/series.ts): only rows still
-- 'scheduled' AND dated today or later (Asia/Jerusalem). Completed rows
-- already moved packages.used_sessions (trg_increment_used_sessions) and count
-- in trainer_monthly_money; past ones are history.
--
-- Re-runnable.

alter table public.scheduled_workouts
  add column if not exists series_id uuid;

-- "This and all future" looks up a trainer's series from a date on.
create index if not exists scheduled_workouts_series_idx
  on public.scheduled_workouts (trainer_id, series_id, scheduled_date)
  where series_id is not null;
